input.sparql:
SELECT DISTINCT ?z ?zlabel ?pt ?ptcls ?ref
WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?zlabel .
  FILTER (str(?zlabel) = "Perimeter_top_ZN_4")
}

SELECT DISTINCT ?pt ?ptcls WHERE {
  ?pt brick:isPointOf ?z .
  ?pt a brick:Zone .
  ?z rdfs:label ?zl .
  FILTER (str(?zl) = "Perimeter_top_ZN_4")
}

SELECT DISTINCT ?z ?zl ?pt WHERE {
  ?z rdfs:label ?zl .
  ?pt brick:isPointOf ?z .
  FILTER (CONTAINS(str(?zl), "Perimeter_top_ZN_4"))
}
LIMIT 40
